#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *push_front(struct Node *head, int value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->value = value;
    node->next = head;
    return node;
}

int main() {
    struct Node *head = NULL;
    for (int v = 3; v >= 1; v--) {
        head = push_front(head, v);
    }
    struct Node *p = head;
    while (p != NULL) {
        printf("%d\n", p->value);
        struct Node *next = p->next;
        free(p);
        p = next;
    }
    return 0;
}
